func (e *LoadedEventDecoder) Decode(data []byte) (LoadedEvent, error) {
	return e.decodeImpl(data)
}

// MustDecode decodes log data for Loaded event
func (e *LoadedEventDecoder) MustDecode(data []byte) LoadedEvent {
	result, err := e.decodeImpl(data)
	if err != nil {
		panic(err)
	}
	return result
}

// DecodeLog decodes a full log into LoadedEvent: non-indexed parameters are
// read from data, while indexed parameters are read from topics (topics[0] is the
// event signature, so indexed params start at topics[1]) in ABI order.
//
// Indexed dynamic types (string, bytes, arrays) are stored as the keccak hash of
// their value in the topic and cannot be recovered to their original value; such
// fields are left at their zero value.
func (e *LoadedEventDecoder) DecodeLog(topics [][32]byte, data []byte) (LoadedEvent, error) {
	// Non-indexed parameters live in the data section.
	result, err := e.decodeImpl(data)
	if err != nil {
		return result, err
	}
	// Indexed parameters live in the log topics, after the signature topic.
	topicIndex := 1
	if len(topics) <= topicIndex {
		return result, errors.New("missing topic for indexed parameter key")
	}
	{
		word := topics[topicIndex][:]
		v, e := decodeUint256(word)
		if e != nil {
			return result, fmt.Errorf("decoding indexed parameter key: %w", e)
		}
		result.Key = v
	}
	topicIndex++
	return result, nil
}

// decodeImpl contains the actual decode logic
func (e *LoadedEventDecoder) decodeImpl(data []byte) (LoadedEvent, error) {
	// Decode event parameters (only non-indexed parameters are in data)
	var result LoadedEvent
	offset := 0
	if len(data) < offset+32 {
		return result, errors.New("insufficient data for event parameter value")
	}
	{
		v, e := decodeUint256(data[offset : offset+32])
		if e != nil {
			return result, fmt.Errorf("decoding event parameter value: %w", e)
		}
		result.Value = v
	}
	offset += 32
	return result, nil
}

